bounded_host_request.command:
set -eu
r=/home/gace/Project/Gserver/projects/TGtumbler/GateApp-Bot
w="$r/.worktrees/room-live-2467fe6"
for name in userbot_keepalive.py userbot_resident_ipc.py userbot_test_client.py userbot_room_smoke.py; do
 if test -f "$r/scripts/$name"; then
  echo ROOT_"$name"=PRESENT; sha256sum "$r/scripts/$name" | cut -d' ' -f1
 else echo ROOT_"$name"=ABSENT; fi
 if test -f "$w/scripts/$name"; then
  echo WORKTREE_"$name"=PRESENT; sha256sum "$w/scripts/$name" | cut -d' ' -f1
 else echo WORKTREE_"$name"=ABSENT; fi
done
echo UNIT_RELOAD_CAPABLE=$(systemctl --user cat gace-userbot-verify.service | grep -Eq '^ExecReload=' && echo YES || echo NO)
echo ROOT_KEEPALIVE_IPC_IMPORT=$(grep -q '^from userbot_resident_ipc import serve_resident' "$r/scripts/userbot_keepalive.py" 2>/dev/null && echo YES || echo NO)
echo ROOT_SCRIPT_TRACKED=$(git -C "$r" ls-files --error-unmatch scripts/userbot_keepalive.py >/dev/null 2>&1 && echo YES || echo NO)
echo ROOT_DIRTY_COUNT=$(git -C "$r" status --porcelain --untracked-files=no | wc -l)
echo USERBOT_PID=$(systemctl --user show gace-userbot-verify.service -p MainPID --value)
echo UNIT_ACTIVE=$(systemctl --user is-active gace-userbot-verify.service || :)
echo READONLY_ROOT_CODE_PRECHECK_DONE
